const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  const point = ee.Geometry.Point(35.114837, 11.184384);
  // Use a 100-meter buffer around the point to define "around the location".
  const analysisArea = point.buffer(100); 

  // Dates for comparison
  const date2022_start = '2022-02-14';
  const date2022_end = '2022-02-15'; // Narrow window for the specific date
  const date2019_start = '2019-02-06';
  const date2019_end = '2019-02-07'; // Narrow window for the specific date

  // Sentinel-2 SR (Level-2A) collection for surface reflectance
  const S2_SR_COLLECTION = 'COPERNICUS/S2_SR_HARMONIZED';

  // Function to mask clouds using the SCL band for Sentinel-2 Level-2A data
  function maskS2clouds(image) {
    const s2CloudlessThreshold = 20; // Cloud probability threshold for s2cloudless
    const qa = image.select('SCL');
    // Values 3 (cloud shadow), 8 (clouds medium probability), 9 (clouds high probability), 10 (cirrus)
    const cloudMask = qa.neq(3).and(qa.neq(8)).and(qa.neq(9)).and(qa.neq(10));
    return image.updateMask(cloudMask);
  }

  // Function to calculate MNDWI (Modified Normalized Difference Water Index)
  // MNDWI = (Green - SWIR1) / (Green + SWIR1)
  function addMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // Process images for a given date range
  async function processImages(startDate, endDate, description) {
    let collection = ee.ImageCollection(S2_SR_COLLECTION)
      .filterBounds(analysisArea)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Filter by metadata cloud cover

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`${description} Images: 0`);
      return null;
    }

    // Select the least cloudy image within the collection
    const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();

    // Apply cloud mask and calculate MNDWI
    const maskedImage = maskS2clouds(image).map(addMNDWI).first();

    const cloudPixelPercentage = image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();

    // Calculate valid pixel count for the MNDWI band
    const validPixelsCount = await maskedImage.select('MNDWI')
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: analysisArea,
        scale: 10, // Sentinel-2 resolution
        maxPixels: 1e9
      }).get('MNDWI').getInfo();

    console.log(`${description} Images: ${collectionSize} (Cloud%: ${cloudPixelPercentage.toFixed(2)}, Valid Pixels: ${validPixelsCount})`);

    if (validPixelsCount === 0) {
      return { image: null, pixels: 0, description: description };
    }

    // Classify water (MNDWI > 0)
    const waterMask = maskedImage.select('MNDWI').gt(0).rename('water');
    const waterImage = maskedImage.updateMask(waterMask);

    // Calculate water extent (number of water pixels * pixel area)
    const waterPixels = await waterImage.select('water')
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: analysisArea,
        scale: 10, // Sentinel-2 resolution (10m x 10m = 100 sq meters per pixel)
        maxPixels: 1e9
      }).get('water').getInfo();

    const waterExtentSqM = waterPixels * 10 * 10; // 10m x 10m pixel area

    return { image: maskedImage, waterExtent: waterExtentSqM, pixels: waterPixels, description: description };
  }

  // --- Main Analysis ---
  let result2022 = null;
  let result2019 = null;

  try {
    result2022 = await processImages(date2022_start, date2022_end, "2022-02-14");
    result2019 = await processImages(date2019_start, date2019_end, "2019-02-06");
  } catch (error) {
    console.log("Error during image processing:", error);
    console.log("C3"); // Calculation failure, possibly due to band issues or other GEE errors
    return;
  }

  // Handle C1: Empty Collection
  if (!result2022 || !result2019) {
    console.log("C1");
    return;
  }

  // Handle C2: No Valid Pixels after masking
  if (result2022.pixels === 0 && result2019.pixels === 0) {
    console.log("No valid pixels after masking for both dates.");
    console.log("C2");
    return;
  } else if (result2022.pixels === 0) {
    console.log("No valid pixels for 2022 after masking.");
    console.log("C2");
    return;
  } else if (result2019.pixels === 0) {
    console.log("No valid pixels for 2019 after masking.");
    console.log("C2");
    return;
  }

  const waterExtent2022 = result2022.waterExtent;
  const waterExtent2019 = result2019.waterExtent;

  // Handle C3: Calculation Failure (e.g., if waterExtent is null/NaN)
  if (waterExtent2022 === null || isNaN(waterExtent2022) ||
      waterExtent2019 === null || isNaN(waterExtent2019)) {
    console.log("Water extent calculation resulted in invalid values.");
    console.log("C3");
    return;
  }

  console.log(`Water extent on ${result2022.description}: ${waterExtent2022.toFixed(2)} sq meters.`);
  console.log(`Water extent on ${result2019.description}: ${waterExtent2019.toFixed(2)} sq meters.`);

  if (waterExtent2022 > waterExtent2019) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
